            cells = []
            for y, x in queue:
                cells.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1 and component_id[yy][xx] < 0:
                        component_id[yy][xx] = k
                        queue.append((yy, xx))
            components.append(cells)

    seen = [[False] * w for _ in range(h)]
    zero_components = []
    external = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            queue = [(r, c)]
            seen[r][c] = True
            cells = []
            touches_edge = False
            adjacent_ones = set()
            for y, x in queue:
                cells.append((y, x))
                touches_edge |= y == 0 or x == 0 or y == h - 1 or x == w - 1
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w:
                        if grid[yy][xx] == 0 and not seen[yy][xx]:
                            seen[yy][xx] = True
                            queue.append((yy, xx))
                        elif grid[yy][xx] == 1:
                            adjacent_ones.add(component_id[yy][xx])
            zero_components.append((cells, touches_edge, adjacent_ones))
            if touches_edge:
                external.update(cells)

    closed_components = set()
    for cells, touches_edge, adjacent_ones in zero_components:
