                   for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1))):
                boundary.append((y, x))

        distance = {point: 0 for point in boundary}
        queue = deque(boundary)
        while queue:
            y, x = queue.popleft()
            for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                if (yy, xx) in cell_set and (yy, xx) not in distance:
