    # The exterior border around a closed outline is color 2; interiors are color 3.
    for k in closed_components:
        for y, x in components[k]:
            for yy in range(max(0, y - 1), min(h, y + 2)):
                for xx in range(max(0, x - 1), min(w, x + 2)):
                    if (yy, xx) in external:
                        out[yy][xx] = 2
